"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import {
  Archive, BarChart3, BriefcaseBusiness, CheckCircle2, ClipboardList, CreditCard,
  FileSignature, FileText, KanbanSquare, Loader2, Plus, RefreshCw, Search,
  Sparkles, Upload, Users, X,
} from "lucide-react";
import QuoteEditor from "./QuoteEditor";

const PIPELINE = [
  ["nuovo_contatto", "Nuovo contatto"], ["intervista_pianificata", "Intervista pianificata"],
  ["intervista_completata", "Intervista completata"], ["preventivo_in_preparazione", "Preventivo in preparazione"],
  ["preventivo_pronto", "Preventivo pronto"], ["preventivo_presentato", "Preventivo presentato"],
  ["in_trattativa", "In trattativa"], ["posticipato", "Posticipato"], ["rifiutato", "Rifiutato"],
  ["accettato", "Accettato"], ["in_onboarding", "In onboarding"], ["convertito", "Convertito"],
];
const STATUS_LABELS = Object.fromEntries(PIPELINE);
const money = (value) => new Intl.NumberFormat("it-IT", { style: "currency", currency: "EUR" }).format(Number(value) || 0);
const date = (value) => value ? new Intl.DateTimeFormat("it-IT", { dateStyle: "medium" }).format(new Date(value)) : "-";
const cx = (...items) => items.filter(Boolean).join(" ");

async function api(path, options) {
  const response = await fetch(path, { cache: "no-store", ...options, headers: options?.body instanceof FormData ? options.headers : { "Content-Type": "application/json", ...(options?.headers || {}) } });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    const error = new Error(payload.error || payload.message || "Operazione non riuscita");
    error.status = response.status; error.payload = payload; throw error;
  }
  return payload;
}

function Modal({ title, children, onClose, wide = false }) {
  return <div className="fixed inset-0 z-[60] bg-gray-950/60 p-4 overflow-y-auto"><div className={cx("mx-auto my-8 bg-white rounded-2xl shadow-2xl", wide ? "max-w-5xl" : "max-w-2xl")}><div className="flex items-center justify-between border-b px-6 py-4"><h2 className="text-xl font-bold">{title}</h2><button onClick={onClose} className="p-2 rounded-lg hover:bg-gray-100"><X /></button></div><div className="p-6">{children}</div></div></div>;
}

function Field({ label, children, className }) {
  return <label className={cx("block text-sm", className)}><span className="block mb-1 font-medium text-gray-700">{label}</span>{children}</label>;
}

const inputClass = "w-full rounded-lg border border-gray-300 bg-white px-3 py-2 outline-none focus:border-yellow-500 focus:ring-2 focus:ring-yellow-200";
const button = "inline-flex items-center justify-center gap-2 rounded-lg px-4 py-2 text-sm font-semibold transition disabled:opacity-40";

export default function CommercialeClient({ adminEmail }) {
  const [tab, setTab] = useState("dashboard");
  const [data, setData] = useState({ contacts: [], opportunities: [], interviews: [], interviewTemplates: [], quotes: [], quoteTemplates: [], contracts: [], payments: [], transactions: [], collaborations: [] });
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [notice, setNotice] = useState("");
  const [search, setSearch] = useState("");
  const [modal, setModal] = useState(null);
  const [editingQuote, setEditingQuote] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [contacts, opportunities, interviews, interviewTemplates, quotes, quoteTemplates, contracts, payments, transactions, collaborations] = await Promise.all([
        api("/api/commerciale/contacts"), api("/api/commerciale/opportunities"), api("/api/commerciale/interviews"),
        api("/api/commerciale/interview-templates"), api("/api/commerciale/quotes"), api("/api/commerciale/quote-templates"),
        api("/api/commerciale/contracts"), api("/api/commerciale/payments"), api("/api/commerciale/transactions"), api("/api/commerciale/collaborations"),
      ]);
      setData({ contacts, opportunities, interviews, interviewTemplates, quotes, quoteTemplates, contracts, payments, transactions, collaborations });
    } catch (error) { setNotice(error.message); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { load(); }, [load]);

  const mutate = async (work, success = "Salvato") => {
    setBusy(true); setNotice("");
    try { const result = await work(); setNotice(success); await load(); return result; }
    catch (error) { setNotice(error.message); throw error; }
    finally { setBusy(false); }
  };

  const metrics = useMemo(() => {
    const accepted = data.quotes.filter((item) => item.status === "accepted");
    const open = data.opportunities.filter((item) => !["rifiutato", "convertito"].includes(item.state));
    const acceptedValue = accepted.reduce((sum, quote) => sum + (quote.versions.find((version) => version.version === quote.acceptedVersion)?.totals?.gross || 0), 0);
    const opportunityValue = open.reduce((sum, item) => sum + (item.estimatedValue || 0), 0);
    return { contacts: data.contacts.length, open: open.length, interviews: data.interviews.filter((item) => item.status !== "completed").length, draftQuotes: data.quotes.filter((item) => item.status === "draft").length, accepted: accepted.length, rejected: data.quotes.filter((item) => item.status === "rejected").length, converted: data.opportunities.filter((item) => item.state === "convertito").length, opportunityValue, acceptedValue, conversion: data.opportunities.length ? Math.round((data.opportunities.filter((item) => item.state === "convertito").length / data.opportunities.length) * 100) : 0 };
  }, [data]);

  const nav = [
    ["dashboard", "Dashboard", BarChart3], ["contacts", "Contatti", Users], ["interviews", "Interviste", ClipboardList],
    ["quotes", "Preventivi", FileText], ["templates", "Template", Sparkles], ["pipeline", "Pipeline", KanbanSquare],
    ["payments", "Pagamenti", CreditCard], ["archive", "Archivio", Archive],
  ];

  if (loading && !data.contacts.length) return <div className="min-h-[60vh] grid place-items-center"><div className="text-center"><Loader2 className="w-9 h-9 animate-spin mx-auto text-yellow-500" /><p className="mt-3 text-gray-500">Caricamento area commerciale…</p></div></div>;

  return <div className="space-y-6">
    <div className="rounded-3xl bg-black text-white p-6 md:p-8 overflow-hidden relative"><div className="absolute right-0 top-0 h-full w-1/3 bg-yellow-300/90 skew-x-[-12deg] translate-x-1/3" /><div className="relative"><p className="text-yellow-300 text-xs uppercase tracking-[0.25em]">Hoon gestionale</p><h1 className="mt-2 text-3xl md:text-4xl font-black">COMMERCIALE</h1><p className="mt-2 text-gray-300">Dal primo contatto all&apos;attivazione della collaborazione.</p><p className="mt-5 text-xs text-gray-500">Accesso esclusivo: {adminEmail}</p></div></div>

    <div className="flex gap-2 overflow-x-auto pb-1">{nav.map(([id, label, Icon]) => <button key={id} onClick={() => setTab(id)} className={cx(button, "shrink-0", tab === id ? "bg-yellow-300 text-black" : "bg-white border text-gray-700 hover:bg-gray-50")}><Icon className="w-4 h-4" />{label}</button>)}</div>
    {notice && <div className="rounded-xl border border-yellow-300 bg-yellow-50 px-4 py-3 text-sm flex justify-between"><span>{notice}</span><button onClick={() => setNotice("")}><X className="w-4 h-4" /></button></div>}

    {tab === "dashboard" && <Dashboard metrics={metrics} opportunities={data.opportunities} payments={data.payments} setTab={setTab} />}
    {tab === "contacts" && <Contacts data={data} search={search} setSearch={setSearch} setModal={setModal} />}
    {tab === "interviews" && <Interviews data={data} setModal={setModal} mutate={mutate} busy={busy} />}
    {tab === "quotes" && <Quotes data={data} setModal={setModal} setEditingQuote={setEditingQuote} />}
    {tab === "templates" && <Templates data={data} mutate={mutate} busy={busy} setModal={setModal} />}
    {tab === "pipeline" && <Pipeline data={data} mutate={mutate} />}
    {tab === "payments" && <Payments data={data} setModal={setModal} mutate={mutate} />}
    {tab === "archive" && <ArchiveView data={data} setModal={setModal} mutate={mutate} />}

    {modal === "contact" && <ContactForm onClose={() => setModal(null)} mutate={mutate} busy={busy} />}
    {modal === "interview" && <InterviewForm data={data} onClose={() => setModal(null)} mutate={mutate} busy={busy} />}
    {modal === "quote" && <QuoteForm data={data} onClose={() => setModal(null)} mutate={mutate} busy={busy} />}
    {modal === "contract" && <ContractForm data={data} onClose={() => setModal(null)} mutate={mutate} busy={busy} />}
    {modal === "payment" && <PaymentForm data={data} onClose={() => setModal(null)} mutate={mutate} busy={busy} />}
    {modal === "import-template" && <TemplateImport onClose={() => setModal(null)} mutate={mutate} busy={busy} />}
    {editingQuote && <QuoteEditor quote={editingQuote} onClose={() => { setEditingQuote(null); load(); }} onSaved={(updated) => setEditingQuote((old) => ({ ...old, ...updated, organization: old.organization, opportunity: old.opportunity }))} />}
  </div>;
}

function Dashboard({ metrics, opportunities, payments, setTab }) {
  const cards = [["Contatti", metrics.contacts, Users], ["Trattative aperte", metrics.open, BriefcaseBusiness], ["Interviste da completare", metrics.interviews, ClipboardList], ["Preventivi in bozza", metrics.draftQuotes, FileText], ["Preventivi accettati", metrics.accepted, CheckCircle2], ["Tasso conversione", `${metrics.conversion}%`, BarChart3]];
  return <div className="space-y-6"><div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">{cards.map(([label, value, Icon]) => <div key={label} className="bg-white border rounded-2xl p-5"><div className="flex justify-between"><p className="text-sm text-gray-500">{label}</p><Icon className="w-5 h-5 text-gray-400" /></div><p className="mt-3 text-3xl font-black">{value}</p></div>)}</div><div className="grid lg:grid-cols-2 gap-5"><div className="bg-white border rounded-2xl p-6"><h2 className="font-bold">Valore commerciale</h2><div className="mt-5 grid grid-cols-2 gap-4"><div><p className="text-sm text-gray-500">Opportunità (non incassato)</p><p className="text-2xl font-bold mt-1">{money(metrics.opportunityValue)}</p></div><div><p className="text-sm text-gray-500">Preventivi accettati</p><p className="text-2xl font-bold mt-1">{money(metrics.acceptedValue)}</p></div></div></div><div className="bg-white border rounded-2xl p-6"><h2 className="font-bold">Attenzione amministrativa</h2><div className="mt-4 space-y-2 text-sm"><button onClick={() => setTab("pipeline")} className="w-full flex justify-between border rounded-lg p-3"><span>Posticipati</span><strong>{opportunities.filter((item) => item.state === "posticipato").length}</strong></button><button onClick={() => setTab("payments")} className="w-full flex justify-between border rounded-lg p-3"><span>Pagamenti falliti/scaduti</span><strong>{payments.filter((item) => item.status === "past_due").length}</strong></button></div></div></div></div>;
}

function Contacts({ data, search, setSearch, setModal }) {
  const filtered = data.contacts.filter((item) => `${item.businessName} ${item.tradingName} ${item.people?.map((person) => `${person.firstName} ${person.lastName} ${person.email}`).join(" ")}`.toLowerCase().includes(search.toLowerCase()));
  return <section className="bg-white border rounded-2xl overflow-hidden"><div className="p-5 border-b flex flex-col sm:flex-row gap-3 justify-between"><div><h2 className="text-xl font-bold">Contatti commerciali</h2><p className="text-sm text-gray-500">Una azienda può avere più referenti e più opportunità.</p></div><button onClick={() => setModal("contact")} className={cx(button, "bg-black text-white")}><Plus className="w-4 h-4" />Nuovo contatto</button></div><div className="p-4 border-b"><div className="relative"><Search className="absolute left-3 top-2.5 w-4 h-4 text-gray-400" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Cerca azienda, referente o email" className={cx(inputClass, "pl-9")} /></div></div><div className="divide-y">{filtered.map((contact) => { const opps = data.opportunities.filter((item) => String(item.organization?._id || item.organization) === contact._id); const primary = contact.people?.find((person) => person.primary) || contact.people?.[0]; return <article key={contact._id} className="p-5 flex flex-col md:flex-row md:items-center gap-4"><div className="w-12 h-12 rounded-xl bg-yellow-300 grid place-items-center font-black text-lg">{contact.businessName.slice(0, 2).toUpperCase()}</div><div className="min-w-0 flex-1"><h3 className="font-bold text-lg">{contact.tradingName || contact.businessName}</h3><p className="text-sm text-gray-500">{contact.businessName} · {contact.sector || "Settore non indicato"}</p><p className="text-sm mt-1">{primary ? `${primary.firstName} ${primary.lastName} · ${primary.phone || primary.email}` : "Nessun referente"}</p></div><div className="md:text-right"><p className="text-xs text-gray-500">Opportunità</p><p className="font-bold">{opps.length}</p><p className="text-xs text-gray-500 mt-1">Prossimo contatto: {date(contact.nextContactAt)}</p></div></article>; })}{!filtered.length && <p className="p-10 text-center text-gray-500">Nessun contatto trovato.</p>}</div></section>;
}

function ContactForm({ onClose, mutate, busy }) {
  const [form, setForm] = useState({ businessName: "", tradingName: "", sector: "", website: "", vatNumber: "", taxCode: "", firstName: "", lastName: "", phone: "", email: "", role: "", acquisitionSource: "", services: "", budget: "", notes: "", opportunityTitle: "", nextContactAt: "" });
  const change = (key, value) => setForm((old) => ({ ...old, [key]: value }));
  const submit = async (event) => { event.preventDefault(); try { await mutate(async () => { let contact; try { contact = await api("/api/commerciale/contacts", { method: "POST", body: JSON.stringify({ businessName: form.businessName, tradingName: form.tradingName, sector: form.sector, website: form.website, vatNumber: form.vatNumber, taxCode: form.taxCode, acquisitionSource: form.acquisitionSource, requestedServices: form.services.split(",").map((item) => item.trim()).filter(Boolean), indicativeBudget: Number(form.budget) || null, notes: form.notes, nextContactAt: form.nextContactAt || null, assignedCommercial: "marcocerweb@gmail.com", people: [{ firstName: form.firstName, lastName: form.lastName, phone: form.phone, email: form.email, role: form.role, primary: true }] }) }); } catch (error) { if (error.status === 409 && window.confirm(`Possibile duplicato: ${error.payload?.duplicate?.businessName}. Creare comunque?`)) contact = await api("/api/commerciale/contacts", { method: "POST", body: JSON.stringify({ businessName: form.businessName, confirmDuplicate: true, people: [{ firstName: form.firstName, lastName: form.lastName, phone: form.phone, email: form.email, primary: true }] }) }); else throw error; } await api("/api/commerciale/opportunities", { method: "POST", body: JSON.stringify({ organization: contact._id, title: form.opportunityTitle || `Proposta ${form.businessName}`, services: form.services.split(",").map((item) => item.trim()).filter(Boolean), assignedCommercial: "marcocerweb@gmail.com", estimatedValue: Number(form.budget) || 0, nextContactAt: form.nextContactAt || null }) }); }, "Contatto e opportunità creati"); onClose(); } catch {} };
  return <Modal title="Nuovo contatto e opportunità" onClose={onClose}><form onSubmit={submit} className="space-y-5"><div className="grid sm:grid-cols-2 gap-4"><Field label="Ragione sociale *"><input required value={form.businessName} onChange={(e) => change("businessName", e.target.value)} className={inputClass} /></Field><Field label="Nome commerciale"><input value={form.tradingName} onChange={(e) => change("tradingName", e.target.value)} className={inputClass} /></Field><Field label="Settore"><input value={form.sector} onChange={(e) => change("sector", e.target.value)} className={inputClass} /></Field><Field label="Sito web"><input value={form.website} onChange={(e) => change("website", e.target.value)} className={inputClass} /></Field><Field label="Partita IVA"><input value={form.vatNumber} onChange={(e) => change("vatNumber", e.target.value)} className={inputClass} /></Field><Field label="Codice fiscale"><input value={form.taxCode} onChange={(e) => change("taxCode", e.target.value)} className={inputClass} /></Field></div><h3 className="font-bold border-t pt-4">Referente principale</h3><div className="grid sm:grid-cols-2 gap-4">{[["Nome", "firstName"], ["Cognome", "lastName"], ["Telefono", "phone"], ["Email", "email"], ["Ruolo", "role"]].map(([label, key]) => <Field key={key} label={label}><input type={key === "email" ? "email" : "text"} value={form[key]} onChange={(e) => change(key, e.target.value)} className={inputClass} /></Field>)}</div><h3 className="font-bold border-t pt-4">Prima opportunità</h3><div className="grid sm:grid-cols-2 gap-4"><Field label="Titolo"><input value={form.opportunityTitle} onChange={(e) => change("opportunityTitle", e.target.value)} className={inputClass} /></Field><Field label="Servizi richiesti (separati da virgola)"><input value={form.services} onChange={(e) => change("services", e.target.value)} className={inputClass} /></Field><Field label="Budget indicativo"><input type="number" min="0" value={form.budget} onChange={(e) => change("budget", e.target.value)} className={inputClass} /></Field><Field label="Prossimo ricontatto"><input type="datetime-local" value={form.nextContactAt} onChange={(e) => change("nextContactAt", e.target.value)} className={inputClass} /></Field></div><Field label="Note"><textarea rows={3} value={form.notes} onChange={(e) => change("notes", e.target.value)} className={inputClass} /></Field><div className="flex justify-end gap-2"><button type="button" onClick={onClose} className={cx(button, "border")}>Annulla</button><button disabled={busy} className={cx(button, "bg-black text-white")}>{busy ? "Creazione…" : "Crea"}</button></div></form></Modal>;
}

function Interviews({ data, setModal, mutate, busy }) {
  const [selected, setSelected] = useState(null);
  const current = selected && data.interviews.find((item) => item._id === selected._id) || selected;
  if (current) return <InterviewEditor interview={current} onBack={() => setSelected(null)} mutate={mutate} busy={busy} />;
  return <section className="bg-white border rounded-2xl"><div className="p-5 border-b flex justify-between"><div><h2 className="text-xl font-bold">Interviste</h2><p className="text-sm text-gray-500">Compilazione digitale, OCR e analisi AI.</p></div><button onClick={() => setModal("interview")} className={cx(button, "bg-black text-white")}><Plus className="w-4 h-4" />Nuova intervista</button></div><div className="grid md:grid-cols-2 xl:grid-cols-3 gap-4 p-5">{data.interviews.map((item) => <button key={item._id} onClick={() => setSelected(item)} className="text-left border rounded-xl p-4 hover:border-yellow-500"><div className="flex justify-between gap-3"><h3 className="font-bold">{item.title}</h3><span className="text-xs rounded-full bg-gray-100 px-2 py-1">{item.status}</span></div><p className="text-sm text-gray-500 mt-2">{item.organization?.businessName}</p><p className="text-xs text-gray-400 mt-4">Aggiornata {date(item.updatedAt)}</p></button>)}{!data.interviews.length && <p className="text-gray-500">Nessuna intervista.</p>}</div></section>;
}

function InterviewForm({ data, onClose, mutate, busy }) {
  const [form, setForm] = useState({ opportunity: "", template: "", title: "" });
  const submit = async (event) => { event.preventDefault(); const opp = data.opportunities.find((item) => item._id === form.opportunity); const template = data.interviewTemplates.find((item) => item._id === form.template); try { await mutate(() => api("/api/commerciale/interviews", { method: "POST", body: JSON.stringify({ organization: opp.organization?._id || opp.organization, opportunity: opp._id, template: template._id, title: form.title || `${template.name} - ${opp.organization?.businessName}`, answers: template.questions.map((question) => ({ questionKey: question.key, value: "", confidence: 1, confirmed: false, source: "manual" })) }) }), "Intervista creata"); onClose(); } catch {} };
  return <Modal title="Nuova intervista" onClose={onClose}><form onSubmit={submit} className="space-y-4"><Field label="Opportunità *"><select required value={form.opportunity} onChange={(e) => setForm((old) => ({ ...old, opportunity: e.target.value }))} className={inputClass}><option value="">Seleziona…</option>{data.opportunities.map((item) => <option key={item._id} value={item._id}>{item.organization?.businessName} · {item.title}</option>)}</select></Field><Field label="Template *"><select required value={form.template} onChange={(e) => setForm((old) => ({ ...old, template: e.target.value }))} className={inputClass}><option value="">Seleziona…</option>{data.interviewTemplates.map((item) => <option key={item._id} value={item._id}>{item.name}</option>)}</select></Field><Field label="Titolo"><input value={form.title} onChange={(e) => setForm((old) => ({ ...old, title: e.target.value }))} className={inputClass} /></Field><div className="flex justify-end"><button disabled={busy} className={cx(button, "bg-black text-white")}>Crea intervista</button></div></form></Modal>;
}

function InterviewEditor({ interview, onBack, mutate, busy }) {
  const [answers, setAnswers] = useState(interview.answers || []);
  const [notes, setNotes] = useState(interview.notes || "");
  const [file, setFile] = useState(null);
  const questions = interview.template?.questions || [];
  const save = (status = interview.status) => mutate(() => api(`/api/commerciale/interviews/${interview._id}`, { method: "PATCH", body: JSON.stringify({ answers, notes, status, opportunity: interview.opportunity?._id || interview.opportunity }) }), status === "completed" ? "Intervista completata" : "Bozza salvata");
  const extract = async () => { if (!file) return; await mutate(async () => { const form = new FormData(); form.append("file", file); form.append("purpose", "interview_attachment"); const uploaded = await api("/api/commerciale/files", { method: "POST", body: form }); const result = await api("/api/commerciale/ai", { method: "POST", body: JSON.stringify({ action: "extract_interview", fileId: uploaded._id, templateId: interview.template?._id || interview.template }) }); setAnswers(result.answers || []); await api(`/api/commerciale/interviews/${interview._id}`, { method: "PATCH", body: JSON.stringify({ answers: result.answers || [], status: "to_confirm", attachmentIds: [...(interview.attachmentIds || []).map((item) => item._id || item), uploaded._id] }) }); }, "Risposte estratte: verifica quelle con bassa confidenza"); };
  const analyze = () => mutate(() => api("/api/commerciale/ai", { method: "POST", body: JSON.stringify({ action: "analyze_interview", interviewId: interview._id }) }), "Analisi AI completata");
  return <section className="bg-white border rounded-2xl overflow-hidden"><div className="p-5 border-b flex flex-wrap gap-3 items-center"><button onClick={onBack} className={cx(button, "border")}>← Elenco</button><div className="mr-auto"><h2 className="text-xl font-bold">{interview.title}</h2><p className="text-sm text-gray-500">{interview.organization?.businessName} · {interview.template?.name}</p></div><button onClick={() => save()} disabled={busy} className={cx(button, "border")}>Salva bozza</button><button onClick={() => save("completed")} disabled={busy} className={cx(button, "bg-green-600 text-white")}>Concludi</button><button onClick={analyze} disabled={busy || interview.status !== "completed"} className={cx(button, "bg-yellow-300")}><Sparkles className="w-4 h-4" />Analizza con AI</button></div><div className="p-5 grid lg:grid-cols-[1fr_360px] gap-6"><div className="space-y-4">{questions.map((question) => { const answerIndex = answers.findIndex((answer) => answer.questionKey === question.key); const answer = answers[answerIndex] || { questionKey: question.key, value: "", confidence: 1, confirmed: false, source: "manual" }; return <Field key={question.key} label={`${question.label}${question.required ? " *" : ""}`}><textarea required={question.required} value={answer.value || ""} onChange={(e) => { const next = [...answers]; const value = { ...answer, value: e.target.value, confirmed: true }; if (answerIndex >= 0) next[answerIndex] = value; else next.push(value); setAnswers(next); }} rows={question.type === "textarea" ? 4 : 2} className={cx(inputClass, answer.confidence < 0.7 && "border-orange-400 bg-orange-50")} />{answer.source !== "manual" && <span className="text-xs text-gray-500">Estratta con confidenza {Math.round((answer.confidence || 0) * 100)}%</span>}</Field>; })}<Field label="Note"><textarea value={notes} onChange={(e) => setNotes(e.target.value)} rows={4} className={inputClass} /></Field></div><aside className="space-y-4"><div className="border rounded-xl p-4"><h3 className="font-bold">Importa intervista compilata</h3><p className="text-xs text-gray-500 mt-1">PDF, scansione, JPG, PNG o HEIC. I dati estratti restano da confermare.</p><input type="file" accept="application/pdf,image/jpeg,image/png,image/heic,image/heif" onChange={(e) => setFile(e.target.files?.[0])} className="mt-3 text-sm w-full" /><button onClick={extract} disabled={!file || busy} className={cx(button, "mt-3 w-full bg-black text-white")}><Upload className="w-4 h-4" />Estrai risposte</button></div>{interview.aiAnalysis && <div className="border border-yellow-300 bg-yellow-50 rounded-xl p-4"><h3 className="font-bold">Analisi AI</h3><pre className="mt-3 whitespace-pre-wrap text-xs max-h-[500px] overflow-auto">{JSON.stringify(interview.aiAnalysis, null, 2)}</pre></div>}</aside></div></section>;
}

function Quotes({ data, setModal, setEditingQuote }) {
  return <section className="bg-white border rounded-2xl"><div className="p-5 border-b flex justify-between"><div><h2 className="text-xl font-bold">Preventivi</h2><p className="text-sm text-gray-500">Editor A4, prezzi sincronizzati e versioni immutabili.</p></div><button onClick={() => setModal("quote")} className={cx(button, "bg-black text-white")}><Plus className="w-4 h-4" />Nuovo preventivo</button></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-gray-50 text-left"><tr><th className="p-4">Numero</th><th className="p-4">Cliente</th><th className="p-4">Stato</th><th className="p-4">Versione</th><th className="p-4">Totale</th><th className="p-4" /></tr></thead><tbody className="divide-y">{data.quotes.map((quote) => { const version = quote.versions.find((item) => item.version === quote.currentVersion); return <tr key={quote._id}><td className="p-4 font-semibold">{quote.number}</td><td className="p-4">{quote.organization?.businessName}</td><td className="p-4"><span className="rounded-full bg-gray-100 px-2 py-1 text-xs">{quote.status}</span></td><td className="p-4">v{quote.currentVersion}</td><td className="p-4 font-semibold">{money(version?.totals?.gross)}</td><td className="p-4 text-right"><button onClick={() => setEditingQuote(quote)} className={cx(button, "bg-yellow-300")}>Apri editor</button></td></tr>; })}</tbody></table>{!data.quotes.length && <p className="p-10 text-center text-gray-500">Nessun preventivo.</p>}</div></section>;
}

function QuoteForm({ data, onClose, mutate, busy }) {
  const [form, setForm] = useState({ opportunity: "", template: "", interview: "", validUntil: "", projectDescription: "", paymentConditions: "", service: "", description: "", price: "", vatRate: 22, periodicity: "one_off" });
  const change = (key, value) => setForm((old) => ({ ...old, [key]: value }));
  const submit = async (event) => { event.preventDefault(); const opp = data.opportunities.find((item) => item._id === form.opportunity); try { await mutate(() => api("/api/commerciale/quotes", { method: "POST", body: JSON.stringify({ organization: opp.organization?._id || opp.organization, opportunity: opp._id, template: form.template || null, interview: form.interview || null, validUntil: form.validUntil || null, projectDescription: form.projectDescription, paymentConditions: form.paymentConditions, items: [{ service: form.service, description: form.description, quantity: 1, unitPrice: Number(form.price), standardPrice: Number(form.price), discountedPrice: Number(form.price), vatRate: Number(form.vatRate), periodicity: form.periodicity }] }) }), "Preventivo creato"); onClose(); } catch {} };
  return <Modal title="Nuovo preventivo" onClose={onClose}><form onSubmit={submit} className="space-y-4"><Field label="Opportunità *"><select required value={form.opportunity} onChange={(e) => change("opportunity", e.target.value)} className={inputClass}><option value="">Seleziona…</option>{data.opportunities.map((item) => <option key={item._id} value={item._id}>{item.organization?.businessName} · {item.title}</option>)}</select></Field><div className="grid sm:grid-cols-2 gap-4"><Field label="Template"><select value={form.template} onChange={(e) => change("template", e.target.value)} className={inputClass}><option value="">Template base</option>{data.quoteTemplates.map((item) => <option key={item._id} value={item._id}>{item.name}</option>)}</select></Field><Field label="Intervista"><select value={form.interview} onChange={(e) => change("interview", e.target.value)} className={inputClass}><option value="">Nessuna</option>{data.interviews.filter((item) => !form.opportunity || String(item.opportunity?._id || item.opportunity) === form.opportunity).map((item) => <option key={item._id} value={item._id}>{item.title}</option>)}</select></Field><Field label="Validità"><input type="date" value={form.validUntil} onChange={(e) => change("validUntil", e.target.value)} className={inputClass} /><span /></Field></div><Field label="Descrizione progetto"><textarea rows={3} value={form.projectDescription} onChange={(e) => change("projectDescription", e.target.value)} className={inputClass} /></Field><h3 className="font-bold border-t pt-4">Prima voce economica</h3><div className="grid sm:grid-cols-2 gap-4"><Field label="Servizio *"><input required value={form.service} onChange={(e) => change("service", e.target.value)} className={inputClass} /></Field><Field label="Prezzo netto *"><input required type="number" min="0" step="0.01" value={form.price} onChange={(e) => change("price", e.target.value)} className={inputClass} /></Field><Field label="IVA %"><input type="number" value={form.vatRate} onChange={(e) => change("vatRate", e.target.value)} className={inputClass} /></Field><Field label="Periodicità"><select value={form.periodicity} onChange={(e) => change("periodicity", e.target.value)} className={inputClass}><option value="one_off">Una tantum</option><option value="monthly">Mensile</option><option value="annual">Annuale</option></select></Field></div><Field label="Descrizione voce"><textarea value={form.description} onChange={(e) => change("description", e.target.value)} className={inputClass} /></Field><Field label="Condizioni di pagamento"><textarea rows={3} value={form.paymentConditions} onChange={(e) => change("paymentConditions", e.target.value)} className={inputClass} /></Field><div className="flex justify-end"><button disabled={busy} className={cx(button, "bg-black text-white")}>Crea e apri dopo</button></div></form></Modal>;
}

function Templates({ data, mutate, busy, setModal }) {
  return <div className="grid lg:grid-cols-2 gap-5"><section className="bg-white border rounded-2xl p-5"><div className="flex justify-between"><div><h2 className="text-xl font-bold">Template interviste</h2><p className="text-sm text-gray-500">I PDF vengono proposti dall&apos;AI e salvati solo dopo revisione.</p></div><button onClick={() => setModal("import-template")} className={cx(button, "border")}><Upload className="w-4 h-4" />Importa PDF</button></div><div className="mt-5 space-y-3">{data.interviewTemplates.map((item) => <div key={item._id} className="border rounded-xl p-4"><div className="flex justify-between"><strong>{item.name}</strong><span className="text-xs">v{item.version}</span></div><p className="text-sm text-gray-500 mt-1">{item.questions.length} domande · {item.serviceType}</p></div>)}</div></section><section className="bg-white border rounded-2xl p-5"><h2 className="text-xl font-bold">Template preventivi</h2><p className="text-sm text-gray-500">Ricostruiti come pagine native modificabili, non come immagini.</p><div className="mt-5 space-y-3">{data.quoteTemplates.map((item) => <div key={item._id} className="border rounded-xl p-4 flex justify-between"><div><strong>{item.name}</strong><p className="text-sm text-gray-500">{item.pages.length} pagine A4</p></div><button disabled={busy} onClick={() => mutate(() => api("/api/commerciale/quote-templates", { method: "POST", body: JSON.stringify({ name: `${item.name} copia ${Date.now().toString().slice(-4)}`, description: item.description, pages: item.pages }) }), "Template duplicato")} className={cx(button, "border")}>Duplica</button></div>)}</div></section></div>;
}

function TemplateImport({ onClose, mutate, busy }) {
  const [file, setFile] = useState(null); const [proposal, setProposal] = useState(""); const [sourceFile, setSourceFile] = useState("");
  const analyze = async () => { if (!file) return; try { await mutate(async () => { const form = new FormData(); form.append("file", file); form.append("purpose", "interview_source"); const uploaded = await api("/api/commerciale/files", { method: "POST", body: form }); const result = await api("/api/commerciale/ai", { method: "POST", body: JSON.stringify({ action: "propose_template", fileId: uploaded._id }) }); setSourceFile(uploaded._id); setProposal(JSON.stringify(result.proposal, null, 2)); }, "Proposta pronta: verificala prima di salvare"); } catch {} };
  const save = async () => { try { const parsed = JSON.parse(proposal); await mutate(() => api("/api/commerciale/interview-templates", { method: "POST", body: JSON.stringify({ ...parsed, sourceFile, version: 1, active: true }) }), "Template verificato e salvato"); onClose(); } catch (error) { alert(`JSON non valido: ${error.message}`); } };
  return <Modal title="Importa template intervista" onClose={onClose} wide><div className="space-y-4"><input type="file" accept="application/pdf,image/jpeg,image/png" onChange={(e) => setFile(e.target.files?.[0])} /><button onClick={analyze} disabled={!file || busy} className={cx(button, "bg-black text-white")}><Sparkles className="w-4 h-4" />Analizza senza sovrascrivere</button>{proposal && <><p className="text-sm text-orange-700">Controlla nomi, tipi, obbligatorietà e opzioni. Il salvataggio avviene solo con il pulsante seguente.</p><textarea value={proposal} onChange={(e) => setProposal(e.target.value)} rows={24} className={cx(inputClass, "font-mono text-xs")} /><button onClick={save} disabled={busy} className={cx(button, "bg-green-600 text-white")}>Conferma e salva template</button></>}</div></Modal>;
}

function Pipeline({ data, mutate }) {
  const move = async (opportunity, state) => { if (opportunity.state === state) return; let reason = ""; let resumeAt = null; if (state === "rifiutato") { reason = window.prompt("Motivazione del rifiuto") || ""; if (!reason) return; } if (state === "posticipato") { reason = window.prompt("Motivo del rinvio") || ""; if (!reason) return; resumeAt = window.prompt("Data di ripresa (AAAA-MM-GG)") || ""; if (!resumeAt) return; } await mutate(() => api(`/api/commerciale/opportunities/${opportunity._id}`, { method: "PATCH", body: JSON.stringify({ action: "change_state", state, reason, resumeAt }) }), "Pipeline aggiornata"); };
  return <div className="overflow-x-auto pb-4"><div className="flex gap-4 min-w-max">{PIPELINE.map(([state, label]) => <section key={state} onDragOver={(e) => e.preventDefault()} onDrop={(e) => { const item = data.opportunities.find((opportunity) => opportunity._id === e.dataTransfer.getData("text/plain")); if (item) move(item, state); }} className="w-72 bg-gray-100 border rounded-2xl p-3"><div className="flex justify-between px-1 mb-3"><h3 className="font-bold text-sm">{label}</h3><span className="text-xs rounded-full bg-white px-2 py-0.5">{data.opportunities.filter((item) => item.state === state).length}</span></div><div className="space-y-3 min-h-24">{data.opportunities.filter((item) => item.state === state).map((item) => <article key={item._id} draggable onDragStart={(e) => e.dataTransfer.setData("text/plain", item._id)} className="bg-white rounded-xl border p-3 shadow-sm cursor-grab"><p className="font-semibold">{item.organization?.businessName}</p><p className="text-sm text-gray-600 mt-1">{item.title}</p><div className="flex justify-between mt-3 text-xs text-gray-500"><span>{item.assignedCommercial || "Hoon"}</span><strong>{money(item.estimatedValue)}</strong></div><select value={item.state} onChange={(e) => move(item, e.target.value)} className="mt-3 w-full border rounded p-1 text-xs">{PIPELINE.map(([id, name]) => <option key={id} value={id}>{name}</option>)}</select></article>)}</div></section>)}</div></div>;
}

function Payments({ data, setModal, mutate }) {
  const recurring = data.payments.filter((item) => item.type === "subscription" && item.status === "active").reduce((sum, item) => sum + item.amount, 0);
  const monthStart = new Date(); monthStart.setDate(1); monthStart.setHours(0, 0, 0, 0);
  const actual = data.transactions.filter((item) => item.status === "paid" && new Date(item.occurredAt) >= monthStart).reduce((sum, item) => sum + item.amount, 0);
  const futureInstallments = data.payments.flatMap((plan) => plan.installments || []).filter((item) => !["paid", "cancelled"].includes(item.status)).reduce((sum, item) => sum + item.amount, 0);
  const cards = [["Ricavi ricorrenti mensili", money(recurring)], ["Incassato questo mese", money(actual)], ["Rate future", money(futureInstallments)], ["Abbonamenti attivi", data.payments.filter((item) => item.type === "subscription" && item.status === "active").length], ["Rinnovi hosting", data.payments.filter((item) => item.type === "renewal" && !["cancelled", "completed"].includes(item.status)).length], ["Pagamenti falliti", data.payments.filter((item) => item.status === "past_due").length], ["In attesa autorizzazione", data.payments.filter((item) => item.status === "awaiting_authorization").length]];
  return <div className="space-y-5"><div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">{cards.map(([label, value]) => <div key={label} className="bg-white border rounded-2xl p-5"><p className="text-sm text-gray-500">{label}</p><p className="text-2xl font-black mt-2">{value}</p></div>)}</div><section className="bg-white border rounded-2xl"><div className="p-5 border-b flex justify-between"><h2 className="text-xl font-bold">Piani Stripe</h2><button onClick={() => setModal("payment")} className={cx(button, "bg-black text-white")}><Plus className="w-4 h-4" />Configura pagamenti</button></div><div className="divide-y">{data.payments.map((plan) => <PaymentRow key={plan._id} plan={plan} mutate={mutate} />)}{!data.payments.length && <p className="p-10 text-center text-gray-500">Nessun piano configurato.</p>}</div></section></div>;
}

function PaymentRow({ plan, mutate }) {
  const generate = async () => { const result = await mutate(() => api(`/api/commerciale/payments/${plan._id}/link`, { method: "POST", body: JSON.stringify({ expiresInDays: 14, conditionsText: plan.conditionsText }) }), "Link generato"); if (result?.url) { await navigator.clipboard?.writeText(result.url); window.prompt("Link cliente (copiato negli appunti)", result.url); } };
  return <div className="p-5"><div className="flex flex-col lg:flex-row lg:items-center gap-4"><div className="flex-1"><div className="flex items-center gap-2"><h3 className="font-bold">{plan.organization?.businessName} · {plan.serviceName}</h3><span className={cx("text-xs rounded-full px-2 py-1", plan.status === "active" ? "bg-green-100 text-green-800" : plan.status === "past_due" ? "bg-red-100 text-red-800" : "bg-gray-100")}>{plan.status}</span></div><p className="text-sm text-gray-500 mt-1">{plan.type} · {money(plan.amount)} · Preventivo {plan.quote?.number}</p>{plan.lastError && <p className="text-xs text-red-600 mt-1">{plan.lastError}</p>}</div><button onClick={generate} className={cx(button, "bg-yellow-300")}>Genera link di pagamento</button><button onClick={() => mutate(() => api(`/api/commerciale/payments/${plan._id}/link`, { method: "DELETE" }), "Link revocato")} className={cx(button, "border text-red-600")}>Revoca</button></div>{plan.installments?.some((item) => ["waiting_milestone", "scheduled", "failed"].includes(item.status)) && <div className="mt-4 border-t pt-3 space-y-2">{plan.installments.filter((item) => ["waiting_milestone", "scheduled", "failed"].includes(item.status)).map((item) => <div key={item._id} className="flex items-center justify-between gap-3 text-sm"><span>{item.label} · {money(item.amount)} · {item.status}</span><button onClick={() => { if (window.confirm(`Confermi l'addebito di ${money(item.amount)} per ${item.label}?`)) mutate(() => api(`/api/commerciale/payments/${plan._id}`, { method: "PATCH", body: JSON.stringify({ action: "confirm_installment", installmentId: item._id }) }), "Rata inviata a Stripe"); }} disabled={!plan.paymentMethodAuthorized} className={cx(button, "border")}>{item.dueType === "milestone" ? "Conferma milestone e addebita" : "Addebita rata"}</button></div>)}</div>}</div>;
}

function PaymentForm({ data, onClose, mutate, busy }) {
  const eligibleContracts = data.contracts.filter((item) => item.signatureStatus === "signed" && item.quote?.status === "accepted");
  const [form, setForm] = useState({ contract: "", type: "subscription", serviceName: "", amount: "", vatRate: 22, startsAt: "", durationMonths: 12, billingDay: 1, autoRenewal: true, firstPeriodAmount: "", firstPeriodMonths: 1, conditionsText: "Autorizzo Hoon a effettuare gli addebiti descritti nel piano economico approvato.", installments: [{ label: "Acconto 50%", amount: "", dueType: "date", dueAt: "" }, { label: "Saldo 50%", amount: "", dueType: "milestone", milestone: "Consegna progetto" }] });
  const change = (key, value) => setForm((old) => ({ ...old, [key]: value }));
  const selected = eligibleContracts.find((item) => item._id === form.contract);
  const submit = async (event) => { event.preventDefault(); if (!selected) return; try { await mutate(() => api("/api/commerciale/payments", { method: "POST", body: JSON.stringify({ organization: selected.organization?._id || selected.organization, opportunity: selected.opportunity?._id || selected.opportunity, quote: selected.quote?._id || selected.quote, quoteVersion: selected.quoteVersion, contract: selected._id, type: form.type, serviceName: form.serviceName, amount: Number(form.amount), vatRate: Number(form.vatRate), startsAt: form.startsAt || null, durationMonths: Number(form.durationMonths) || null, billingDay: Number(form.billingDay) || null, autoRenewal: form.autoRenewal, firstPeriodAmount: form.firstPeriodAmount === "" ? null : Number(form.firstPeriodAmount), firstPeriodMonths: Number(form.firstPeriodMonths) || null, conditionsText: form.conditionsText, installments: form.type === "installments" ? form.installments.map((item) => ({ ...item, amount: Number(item.amount), dueAt: item.dueAt || null, status: item.dueType === "milestone" ? "waiting_milestone" : "scheduled" })) : [], renewal: form.type === "renewal" ? { firstChargeAfterMonths: 11, intervalMonths: 12 } : undefined }) }), "Piano pagamenti creato"); onClose(); } catch {} };
  return <Modal title="Configura pagamenti" onClose={onClose} wide><form onSubmit={submit} className="space-y-4"><Field label="Contratto firmato e preventivo accettato *"><select required value={form.contract} onChange={(e) => change("contract", e.target.value)} className={inputClass}><option value="">Seleziona…</option>{eligibleContracts.map((item) => <option key={item._id} value={item._id}>{item.organization?.businessName} · {item.quote?.number} v{item.quoteVersion}</option>)}</select></Field><div className="grid md:grid-cols-3 gap-4"><Field label="Tipo"><select value={form.type} onChange={(e) => change("type", e.target.value)} className={inputClass}><option value="subscription">Abbonamento mensile</option><option value="installments">Rate progetto</option><option value="renewal">Dominio/hosting annuale</option></select></Field><Field label="Servizio *"><input required value={form.serviceName} onChange={(e) => change("serviceName", e.target.value)} className={inputClass} /></Field><Field label="Importo per periodo/rata *"><input required type="number" min="0" step="0.01" value={form.amount} onChange={(e) => change("amount", e.target.value)} className={inputClass} /></Field><Field label="Decorrenza"><input type="date" value={form.startsAt} onChange={(e) => change("startsAt", e.target.value)} className={inputClass} /></Field><Field label="Durata mesi"><input type="number" min="1" value={form.durationMonths} onChange={(e) => change("durationMonths", e.target.value)} className={inputClass} /></Field><Field label="IVA %"><input type="number" min="0" value={form.vatRate} onChange={(e) => change("vatRate", e.target.value)} className={inputClass} /></Field></div>{form.type === "subscription" && <div className="grid sm:grid-cols-3 gap-4 rounded-xl bg-gray-50 p-4"><Field label="Primo periodo"><input type="number" min="0" step="0.01" value={form.firstPeriodAmount} onChange={(e) => change("firstPeriodAmount", e.target.value)} className={inputClass} /></Field><Field label="Mesi promo"><input type="number" min="1" value={form.firstPeriodMonths} onChange={(e) => change("firstPeriodMonths", e.target.value)} className={inputClass} /></Field><Field label="Giorno fatturazione"><input type="number" min="1" max="28" value={form.billingDay} onChange={(e) => change("billingDay", e.target.value)} className={inputClass} /></Field></div>}{form.type === "installments" && <div className="space-y-3 rounded-xl bg-gray-50 p-4"><h3 className="font-bold">Rate</h3>{form.installments.map((item, index) => <div key={index} className="grid md:grid-cols-4 gap-2"><input value={item.label} onChange={(e) => setForm((old) => ({ ...old, installments: old.installments.map((value, i) => i === index ? { ...value, label: e.target.value } : value) }))} className={inputClass} /><input type="number" min="0" step="0.01" value={item.amount} onChange={(e) => setForm((old) => ({ ...old, installments: old.installments.map((value, i) => i === index ? { ...value, amount: e.target.value } : value) }))} className={inputClass} /><select value={item.dueType} onChange={(e) => setForm((old) => ({ ...old, installments: old.installments.map((value, i) => i === index ? { ...value, dueType: e.target.value } : value) }))} className={inputClass}><option value="date">Data</option><option value="days_after_signature">Giorni dalla firma</option><option value="milestone">Milestone</option></select><input value={item.dueType === "milestone" ? item.milestone : item.dueAt} type={item.dueType === "milestone" ? "text" : "date"} onChange={(e) => setForm((old) => ({ ...old, installments: old.installments.map((value, i) => i === index ? { ...value, [item.dueType === "milestone" ? "milestone" : "dueAt"]: e.target.value } : value) }))} className={inputClass} /></div>)}<button type="button" onClick={() => setForm((old) => ({ ...old, installments: [...old.installments, { label: `Rata ${old.installments.length + 1}`, amount: "", dueType: "date", dueAt: "" }] }))} className={cx(button, "border")}>+ Rata</button></div>}{form.type === "renewal" && <div className="rounded-xl bg-yellow-50 border border-yellow-200 p-4 text-sm">Il primo addebito sarà pianificato dopo 11 mesi dalla decorrenza; i successivi ogni 12 mesi. La scadenza tecnica resta separata dal pagamento.</div>}<Field label="Condizioni mostrate al cliente"><textarea required rows={4} value={form.conditionsText} onChange={(e) => change("conditionsText", e.target.value)} className={inputClass} /></Field><div className="flex justify-end"><button disabled={busy || !eligibleContracts.length} className={cx(button, "bg-black text-white")}>Salva configurazione</button></div></form></Modal>;
}

function ArchiveView({ data, setModal, mutate }) {
  return <div className="space-y-5"><section className="bg-white border rounded-2xl"><div className="p-5 border-b flex justify-between"><div><h2 className="text-xl font-bold">Contratti manuali</h2><p className="text-sm text-gray-500">Solo registrazione e caricamento; nessun generatore automatico.</p></div><button onClick={() => setModal("contract")} className={cx(button, "bg-black text-white")}><FileSignature className="w-4 h-4" />Registra contratto</button></div><div className="divide-y">{data.contracts.map((item) => <div key={item._id} className="p-5 flex flex-wrap items-center gap-4"><div className="flex-1"><h3 className="font-bold">{item.organization?.businessName} · {item.collaborationType}</h3><p className="text-sm text-gray-500">{item.quote?.number} v{item.quoteVersion} · {item.signatureStatus} · {date(item.contractDate)}</p></div>{item.document && <a href={`/api/commerciale/files/${item.document._id || item.document}`} target="_blank" className={cx(button, "border")}>Apri PDF</a>}</div>)}</div></section><section className="bg-white border rounded-2xl p-5"><h2 className="text-xl font-bold">Onboarding e attivazioni</h2><div className="mt-4 space-y-3">{data.opportunities.filter((item) => ["accettato", "in_onboarding", "convertito"].includes(item.state)).map((item) => <div key={item._id} className="border rounded-xl p-4 flex flex-wrap items-center gap-3"><div className="flex-1"><h3 className="font-bold">{item.organization?.businessName} · {item.title}</h3><p className="text-sm text-gray-500">{STATUS_LABELS[item.state]}</p></div>{item.state === "accettato" && <button onClick={() => mutate(() => api("/api/commerciale/actions/convert-client", { method: "POST", body: JSON.stringify({ opportunityId: item._id }) }), "Contatto convertito senza duplicare l'anagrafica")} className={cx(button, "bg-yellow-300")}>Converti in cliente</button>}{item.state === "in_onboarding" && <button onClick={() => mutate(() => api("/api/commerciale/actions/activate-collaboration", { method: "POST", body: JSON.stringify({ opportunityId: item._id }) }), "Collaborazione attivata")} className={cx(button, "bg-green-600 text-white")}>Attiva collaborazione</button>}{item.state === "convertito" && <span className="text-sm text-green-700 font-semibold">Collaborazione attiva</span>}</div>)}</div></section></div>;
}

function ContractForm({ data, onClose, mutate, busy }) {
  const accepted = data.quotes.filter((item) => item.status === "accepted"); const [form, setForm] = useState({ quote: "", collaborationType: "", contractDate: "", startsAt: "", endsAt: "", autoRenewal: false, signatureStatus: "to_prepare", notes: "" }); const [file, setFile] = useState(null); const change = (key, value) => setForm((old) => ({ ...old, [key]: value })); const selected = accepted.find((item) => item._id === form.quote);
  const submit = async (event) => { event.preventDefault(); try { await mutate(async () => { let document = null; if (file) { const upload = new FormData(); upload.append("file", file); upload.append("purpose", "contract"); document = await api("/api/commerciale/files", { method: "POST", body: upload }); } return api("/api/commerciale/contracts", { method: "POST", body: JSON.stringify({ organization: selected.organization?._id || selected.organization, opportunity: selected.opportunity?._id || selected.opportunity, quote: selected._id, quoteVersion: selected.acceptedVersion, collaborationType: form.collaborationType, contractDate: form.contractDate || null, startsAt: form.startsAt || null, endsAt: form.endsAt || null, autoRenewal: form.autoRenewal, signatureStatus: form.signatureStatus, notes: form.notes, document: document?._id || null, uploadedAt: document ? new Date() : null }) }); }, "Contratto registrato"); onClose(); } catch {} };
  return <Modal title="Registra contratto manuale" onClose={onClose}><form onSubmit={submit} className="space-y-4"><Field label="Preventivo accettato *"><select required value={form.quote} onChange={(e) => change("quote", e.target.value)} className={inputClass}><option value="">Seleziona…</option>{accepted.map((item) => <option key={item._id} value={item._id}>{item.organization?.businessName} · {item.number} v{item.acceptedVersion}</option>)}</select></Field><div className="grid sm:grid-cols-2 gap-4"><Field label="Tipo collaborazione *"><input required value={form.collaborationType} onChange={(e) => change("collaborationType", e.target.value)} className={inputClass} /></Field><Field label="Stato firma"><select value={form.signatureStatus} onChange={(e) => change("signatureStatus", e.target.value)} className={inputClass}><option value="to_prepare">Da preparare</option><option value="sent">Inviato per firma</option><option value="signed">Firmato</option><option value="cancelled">Annullato</option></select></Field><Field label="Data contratto"><input type="date" value={form.contractDate} onChange={(e) => change("contractDate", e.target.value)} className={inputClass} /></Field><Field label="Decorrenza"><input type="date" value={form.startsAt} onChange={(e) => change("startsAt", e.target.value)} className={inputClass} /></Field><Field label="Scadenza"><input type="date" value={form.endsAt} onChange={(e) => change("endsAt", e.target.value)} className={inputClass} /></Field><Field label="PDF firmato"><input type="file" accept="application/pdf" onChange={(e) => setFile(e.target.files?.[0])} className={inputClass} /></Field></div><Field label="Note"><textarea rows={3} value={form.notes} onChange={(e) => change("notes", e.target.value)} className={inputClass} /></Field><label className="flex gap-2 text-sm"><input type="checkbox" checked={form.autoRenewal} onChange={(e) => change("autoRenewal", e.target.checked)} /> Rinnovo previsto</label><div className="flex justify-end"><button disabled={busy || !accepted.length} className={cx(button, "bg-black text-white")}>Registra</button></div></form></Modal>;
}

